"use client"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { runningCauseColumns } from "@/components/columns/running_cause_column";
import { completedCauseColumns } from "@/components/columns/completed_cause_column";
import { DataTable } from "@/components/table/data-table";
import { useCauses } from "@/hooks/use-causes";
import { useState } from "react";


export default function CausesPage() {
  const [activeTab, setActiveTab] = useState("running");
  const { data: runningCauses, isLoading: isLoadingRunning } = useCauses("running");
  const { data: completedCauses, isLoading: isLoadingCompleted } = useCauses("completed");
  const { data: draftCauses, isLoading: isLoadingDraft } = useCauses("draft");

  const columns = activeTab === "completed" ? completedCauseColumns : runningCauseColumns;
  const data = activeTab === "running" 
    ? runningCauses 
    : activeTab === "completed" 
      ? completedCauses 
      : draftCauses;
  const isLoading = activeTab === "running" 
    ? isLoadingRunning 
    : activeTab === "completed" 
      ? isLoadingCompleted 
      : isLoadingDraft;

  return (
    <div className="flex-1 space-y-4 p-8 pt-6">
      <div className="flex items-center justify-between space-y-2">
        <h2 className="text-3xl font-bold tracking-tight">Causes</h2>
      </div>
      <Tabs defaultValue="running" className="space-y-4" onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="running">Running</TabsTrigger>
          <TabsTrigger value="completed">Completed</TabsTrigger>
          <TabsTrigger value="draft">Draft</TabsTrigger>
        </TabsList>
        <TabsContent value="running" className="space-y-4">
          <DataTable columns={columns} data={data || []} isLoading={isLoading} />
        </TabsContent>
        <TabsContent value="completed" className="space-y-4">
          <DataTable columns={columns} data={data || []} isLoading={isLoading} />
        </TabsContent>
        <TabsContent value="draft" className="space-y-4">
          <DataTable columns={columns} data={data || []} isLoading={isLoading} />
        </TabsContent>
      </Tabs>
    </div>
  );
} 