import { useQuery } from "@tanstack/react-query";
import { Cause } from "@/types/causes";

export function useCauses(status: "running" | "completed" | "draft") {
  return useQuery<Cause[]>({
    queryKey: ["causes", status],
    queryFn: async () => {
      // TODO: Replace with actual API call
      const response = await fetch(`/api/causes?status=${status}`);
      if (!response.ok) throw new Error("Failed to fetch causes");
      return response.json();
    },
  });
} 